problems.solution:
import math

def sigmoid(z):
    return 1 / (1 + math.exp(-z))

def sigmoid_slope(z):
    s = sigmoid(z)
    return s * (1 - s)

def relu(z):
    return max(0, z)

def relu_slope(z):
    return 1 if z > 0 else 0

def gelu(z):
    return z * 0.5 * (1 + math.erf(z / math.sqrt(2)))

import numpy as np

def collapse(W1, b1, W2, b2):
    W = W2 @ W1
    b = W2 @ b1 + b2
    return W, b

def check(x, W1, b1, W2, b2):
    W, b = collapse(W1, b1, W2, b2)
    two = W2 @ (W1 @ x + b1) + b2
    one = W @ x + b
    return np.allclose(two, one)

